#!/usr/bin/env python3
"""Compare narrow dynamic Vulkan bilinear probes with CPU at fixed tolerance."""
import pathlib,json,subprocess,hashlib,time,os,gc
import numpy as np
import torch
root=pathlib.Path('/work');probe=root/'probe';out=root/'outputs';out.mkdir(exist_ok=False);meta=json.loads((probe/'metadata.json').read_text());runner=pathlib.Path('/opt/image-studio/bin/executor_runner');sha=lambda p:hashlib.file_digest(p.open('rb'),'sha256').hexdigest();assert sha(runner)==json.loads(pathlib.Path('/models/manifest.json').read_text())['runner_sha256'];assert os.getuid()==1000 and 990 in os.getgroups() and not pathlib.Path('/dev/kfd').exists();os.sched_setaffinity(0,set(sorted(os.sched_getaffinity(0))[:2]));torch.set_num_threads(2);os.environ['MESA_SHADER_CACHE_DISABLE']='false';os.environ['MESA_SHADER_CACHE_DIR']='/work/cache';os.environ['MESA_SHADER_CACHE_MAX_SIZE']='128M';r={'passed':False,'scope':'Dynamic fixed2 bilinear helper only; no full model or application acceptance','export_metadata':meta,'cases':[]}
try:
 for index,case in enumerate(meta['cases']):
  model=probe/(case['model']+'.pte');assert sha(model)==meta['models'][case['model']]['sha256'];value=np.random.default_rng(case['seed']).standard_normal(case['input_shape'],dtype=np.float32);source=root/'input.bin';value.tofile(source);reference_input=torch.from_numpy(value);reference_input=reference_input.repeat(1,256,1,1) if case['model']=='channels' else reference_input;reference=torch.nn.functional.interpolate(reference_input,scale_factor=2.,mode='bilinear',align_corners=False).numpy().reshape(-1);base=root/'output';cmd=[str(runner),'--model_path='+str(model),'--inputs='+str(source),'--output_file='+str(base),'--input_shape='+','.join(str(x) for x in value.shape),'--cpu_threads=2','--print_output=none'];start=time.monotonic();p=subprocess.run(cmd,capture_output=True,text=True,timeout=60);log=p.stdout+p.stderr;(out/('case-'+str(index)+'.log')).write_text(log);row={**case,'input_sha256':sha(source),'exit_code':p.returncode,'runner_wall_seconds':time.monotonic()-start};r['cases'].append(row);assert p.returncode==0,log[-3000:];file=pathlib.Path(str(base)+'-0.bin');actual=np.fromfile(file,dtype=np.float32);assert actual.size==reference.size and np.isfinite(actual).all();d=np.abs(actual-reference);row.update(output_sha256=sha(file),reference_sha256=hashlib.sha256(reference.tobytes()).hexdigest(),max_abs_error=float(d.max()),outside_float_tolerance=int((d>5e-5+5e-5*np.abs(reference)).sum()),passed=bool(np.allclose(actual,reference,atol=5e-5,rtol=5e-5)));assert row['passed'];file.unlink();source.unlink();(out/'result.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(row),flush=True);del actual,reference,reference_input,d,value;gc.collect()
 r['passed']=True
finally:(out/'result.json').write_text(json.dumps(r,indent=2)+'\n')
print(json.dumps({'passed':r['passed']}),flush=True)
